SELECT 
FROM flow_template t
WHERE 1 = 1

  AND t.code = #{code}


  AND t.form_type = #{formType}


  AND t.status = #{status}

ORDER BY t.code ASC, t.version DESC, t.id DESC

mapper.update:
UPDATE flow_template
SET status = 'archived', updated_by = #{updatedBy}, updated_at = NOW()
WHERE code = #{code} AND status = 'published' AND id <> #{excludeId}

UPDATE flow_template
SET node_count = #{nodeCount}, updated_by = #{updatedBy}, updated_at = NOW()
WHERE id = #{id}
